    if (current && current.body.length) out.push({ ...current, prompt: current.body.join('\n').trim() });
  };
  for (const raw of lines) {
    const t = raw.trim().replace(/^[^A-Za-z0-9]+/, '');
    const m = t.match(/^(IMAGE|VIDEO)\s+(\d+)/i);
    if (m) {
