function filesForStem(saveRoot, stem) {
  if (!fs.existsSync(saveRoot)) return [];
  return fs.readdirSync(saveRoot)
    .map((name) => {
      const m = name.match(/^(.*)_image(\d+)_\d+\.(png|jpe?g|webp|gif)$/i);
      if (!m) return null;
      const fullPath = path.join(saveRoot, name);
      const stat = fs.statSync(fullPath);
      return { stem: m[1], index: Number(m[2]), fullPath, fileName: name, mtimeMs: stat.mtimeMs };
